{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "Model-Based / Model-Free Mixture",
      "description": "Weights the model-based and model-free stage 1 action values to compute a net action value.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a perseveration bonus to the stage 1 logits for the action chosen on the previous trial.",
      "params": [
        {
          "name": "rep",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\nif last_action_1 != -1:\n    stickiness[last_action_1] = 1.0\n    \nlogits_1 = beta * q_net + rep * stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_choice_bias",
      "title": "Stage 1 Choice Bias",
      "description": "Applies an intrinsic bias to the logit of choosing action 0 at stage 1.",
      "params": [
        {
          "name": "bias",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "logits_1[0] += bias  # Apply bias to choice 0",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage 1 model-free value of the chosen action using the stage 2 prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the model-free values of all unchosen actions at both stages towards zero.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_a1 = 1 - action_1[trial]\nq_stage1_mf[unchosen_a1] += decay * (0.0 - q_stage1_mf[unchosen_a1])\n\nfor s in range(2):\n    for a in range(2):\n        if not (s == state_idx and a == action_2[trial]):\n            q_stage2_mf[s, a] += decay * (0.0 - q_stage2_mf[s, a])",
      "expressible_in_slots": true
    }
  ]
}
